template <typename T>
struct SingletonManager {
    static T instance;
    static void init(T val) { instance = val; }
};

// Definition of static member (required for instantiation)
template <typename T>
T SingletonManager<T>::instance = T{};

// 1. Implicit Instantiation of SingletonManager<float>
//    (Code for struct and static float instance generated)
float val_f = 3.14f;
SingletonManager<float>::init(val_f);

// 2. Implicit Instantiation of SingletonManager<int>
//    (Code for struct and static int instance generated)
SingletonManager<int>::init(42);

int i = SingletonManager<int>::instance;
float f = SingletonManager<float>::instance;
